#!/bin/bash -ex
#
# This script should be run any time a new package is added to package.json,
# to ensure that the package is also added to node_modules/.  This is necessary
# to avoid the npm registry at build time as well as locking down exact package
# versions used to avoid unexpected source changes
#

LOCAL_PATH=$(readlink -f $(dirname $0))

NPM_CLI=$LOCAL_PATH/../../../../external/npm/cli.js
if [[ ! -f $NPM_CLI ]]; then
  echo Error: NPM not found: $NPM_CLI
  exit 1
fi

export NPM_CONFIG_ARCH=arm
export NPM_CONFIG_PLATFORM=android
export NPM_CONFIG_LOGLEVEL=http

cd $LOCAL_PATH

if [[ ! -d node_modules ]]; then
  mkdir node_modules
fi

cd node_modules
if [[ -d .git ]]; then
  git rm -r * .bin/ || true
else
  rm -rf * .bin
fi


# Run through all the listed dependencies, installing them individually and in
# such a way that they are fully self-contained with respect to their
# dependencies.
#
# Normally when NPM goes to install "bar" and "foo" already exists, and assuming
# "bar" depends on "foo", it will not install "foo" a second time at
# "node_modules/bar/node_modules/foo" and instead reuse the existing
# "node_modules/foo" install. This feature doesn't work for the
# locked_node_modules area because each locked module may be referenced
# independently.
#
# In other words, good:
#
#   * node_modules/foo
#   * node_modules/bar/node_modules/foo
#
# and bad (default npm behaviour):
#   * node_modules/foo
#   * node_modules/bar
#
rm -rf new_node_modules
mkdir -p new_node_modules/.bin
for mod_ver in $($LOCAL_PATH/list_remote_deps.js -v $LOCAL_PATH/package.json); do
  mod=${mod_ver%%@*}
  if [[ -d new_node_modules/$mod ]]; then
    echo Error: Duplicate dependency: $mod
    exit 1
  fi
  rm -rf dep
  mkdir -p dep/node_modules
  cd dep
  node $NPM_CLI install --ignore-scripts $mod_ver
  cd ..
  mv dep/node_modules/$mod new_node_modules/
  if [[ -d dep/node_modules/.bin ]]; then
    mv dep/node_modules/.bin/* new_node_modules/.bin/
  fi
done
mv new_node_modules/{*,.bin} .
rm -rf new_node_modules dep

if [[ -d .git ]]; then
  git add * .bin/
  git commit -m "Automated update" && git log HEAD~..HEAD || true
fi
